```python
import numpy as np
import cv2
import scipy.fftpack


def compress_block(block, Q):
    dct_block = dct2(block)
    quantized_block = np.round(dct_block / Q)
    return zigzag(quantized_block)


def decompress_block(vector, Q):
    dezigzag_block = zigzag(vector)
    idct_block = idct2(dezigzag_block * Q)
    return np.clip(np.round(idct_block), 0, 255)


def compress_layer(L, Q):
    S = np.array([])
    for w in range(0, L.shape[0], 8):
        for k in range(0, L.shape[1], 8):
            block = L[w:(w+8),k:(k+8)]
            S = np.append(S, compress_block(block, Q))
    return S


def decompress_layer(S, L_shape, Q):
    L = np.zeros(L_shape, dtype=np.uint8)
    num_blocks = S.size // 64

    for idx in range(num_blocks):
        vector = S[idx * 64:(idx + 1) * 64]
        r_idx = (idx // (L_shape[1] // 8)) * 8
        c_idx = (idx % (L_shape[1]// 8)) * 8
        L[r_idx:(r_idx+8), c_idx:(c_idx+8)] = decompress_block(vector, Q)

    return L


def dct2(a):
    return scipy.fftpack.dct(scipy.fftpack.dct(a.astype(float), axis=0, norm='ortho'), axis=1, norm='ortho')


def idct2(a):
    return scipy.fftpack.idct(scipy.fftpack.idct(a.astype(float), axis=0 , norm='ortho'), axis=1 , norm='ortho')


def zigzag(A):
    template = np.array([
            [0,  1,  5,  6,  14, 15, 27, 28],
            [2,  4,  7,  13, 16, 26, 29, 42],
            [3,  8,  12, 17, 25, 30, 41, 43],
            [9,  11, 18, 24, 31, 40, 44, 53],
            [10, 19, 23, 32, 39, 45, 52, 54],
            [20, 22, 33, 38, 46, 51, 55, 60],
            [21, 34, 37, 47, 50, 56, 59, 61],
            [35, 36, 48, 49, 57, 58, 62, 63],
            ])

    if len(A.shape) == 1:
        B = np.zeros((8, 8))

        for r in range(0, 8):
            for c in range(0, 8):
                B[r, c] = A[template[r, c]]
    else:
        B = np.zeros((64,))

        for r in range(0, 8):
            for c in range(0, 8):
                B[template[r, c]] = A[r, c]

    return B


def compress_image(image, chroma_ratio="4:4:4", QY=None, QC=None):
    if QY is None:
        QY = np.ones((8, 8))

    if QC is None:
        QC = np.ones((8, 8))

    if chroma_ratio not in ["4:4:4", "4:2:2"]:
        raise ValueError("Invalid chroma_ratio, valid values: '4:4:4', '4:2:2'")

    YCrCb = cv2.cvtColor(image, cv2.COLOR_RGB2YCrCb).astype(int)

    if chroma_ratio == "4:2:2":
        YCrCb[:, 1::2, 1] = YCrCb[:, ::2, 1]
        YCrCb[:, 1::2, 2] = YCrCb[:, ::2, 2]

    comp_Y = compress_layer(YCrCb[:, :, 0], QY)
    comp_Cb = compress_layer(YCrCb[:, :, 1], QC)
    comp_Cr = compress_layer(YCrCb[:, :, 2], QC)

    shape = YCrCb.shape

    return comp_Y, comp_Cb, comp_Cr, shape


def decompress_image(comp_Y, comp_Cb, comp_Cr, shape, QY=None, QC=None):
    if QY is None:
        QY = np.ones((8, 8))

    if QC is None:
        QC = np.ones((8, 8))

    Y = decompress_layer(comp_Y, (shape[0],shape[1]), QY)
    Cb = decompress_layer(comp_Cb, (shape[0],shape[1]), QC)
    Cr = decompress_layer(comp_Cr, (shape[0],shape[1]), QC)

    out_YCrCb = np.stack([Y, Cb, Cr], axis=-1)
    out_RGB = cv2.cvtColor(out_YCrCb.astype(np.uint8), cv2.COLOR_YCrCb2RGB)

    return out_RGB


if __name__ == '__main__':
    image = cv2.imread('test_image.jpg')
    image = cv2.cvtColor(image, cv2.COLOR_BGR2RGB)

    compressed_Y, compressed_Cb, compressed_Cr, img_shape = compress_image(image, chroma_ratio="4:2:2")
    decompressed_image = decompress_image(compressed_Y, compressed_Cb, compressed_Cr, img_shape)

    cv2.imwrite('decompressed_image.jpg', cv2.cvtColor(decompressed_image, cv2.COLOR_RGB2BGR))
```

