import FarmingCropNFT_ABI from './FarmingCropNFT_ABI.json';

const App = () => {
  const [account, setAccount] = useState('');
  const [contract, setContract] = useState(null);
  const [cropName, setCropName] = useState('');
  const [cropAmount, setCropAmount] = useState('');
  const [cropValue, setCropValue] = useState('');
  const [cropID, setCropID] = useState('');

  const loadBlockchainData = async () => {
    const web3 = new Web3(Web3.givenProvider || 'http://localhost:8545');
    const accounts = await web3.eth.getAccounts();
    setAccount(accounts[0]);

    const networkId = await web3.eth.net.getId();
    const networkData = FarmingCropNFT.networks[networkId];

    if (networkData) {
      const contract = new web3.eth.Contract(
        FarmingCropNFT_ABI,
        networkData.address
      );
      setContract(contract);
    } else {
      alert('FarmingCropNFT contract not deployed to detected network');
    }
  };

  const issueCropNFT = async () => {
    await contract.methods
      .issueCropNFT(cropName, cropAmount, cropValue)
      .send({ from: account })
      .on('transactionHash', (hash) => {
        console.log('hash', hash);
      });
  };

  const destroyCropNFT = async () => {
    await contract.methods
      .destroyCropNFT(cropID)
      .send({ from: account })
      .once('confirmation', (confNumber, receipt) => {
        console.log('Destroy Crop NFT confirmed', receipt);
      });
  };

  return (
    <div>
      <button onClick={loadBlockchainData}>Load Blockchain Data</button>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          issueCropNFT();
        }}
      >
        <label>
          Crop Name:
          <input
            type="text"
            onChange={(e) => setCropName(e.target.value)}
            value={cropName}
          />
        </label>

        <label>
          Crop Amount:
          <input
            type="number"
            onChange={(e) => setCropAmount(e.target.value)}
            value={cropAmount}
          />
        </label>

        <label>
          Crop Value:
          <input
            type="number"
            onChange={(e) => setCropValue(e.target.value)}
            value={cropValue}
          />
        </label>

        <button type="submit">Issue Crop NFT</button>
      </form>

      <form
        onSubmit={(e) => {
          e.preventDefault();
          destroyCropNFT();
        }}
      >
        <label>
          Crop ID:
          <input
            type="number"
            onChange={(e) => setCropID(e.target.value)}
            value={cropID}
          />
        </label>

        <button type="submit">Destroy Crop NFT</button>
      </form>
    </div>
  );
};

export default App;
