	rand.Seed(time.Now().UnixNano())

	population := initializePopulation(conf.NumberOfChromosomes, len(exp.Variable))

	for i := 0; i < len(population); i++ {
		population[i].Score = calculateScore(population[i], exp)
	}

	for gen := 0; gen < conf.NumberOfGenerations; gen++ {
		newPopulation := make([]Chromosome, 0, conf.NumberOfChromosomes)

		for i := 0; i < conf.NumberOfChromosomes; i++ {
			parent1 := selectParent(population)
			parent2 := selectParent(population)

