	totalFixedExp := 0.0
	for _, e := range exp.Fixed {
		totalFixedExp += e
	}
	totalVariableExp := 0.0
	for i, e := range chr.Values {
		totalVariableExp += e * exp.Variable[i]
	}
	totalExp := totalFixedExp + totalVariableExp
	diff := exp.TotalBudget - totalExp
	if diff >= 0 {
		return diff
	}

	penalty := -5.0 * diff
	for i, value := range chr.Values {
		penalty -= value * float64(exp.Priority[i])
	}

	return penalty
