			parent1 := selectParent(population)
			parent2 := selectParent(population)

			child := crossover(parent1, parent2)
			mutate(child, conf.MutationRate)

			child.Fitness = calcFitness(child, exp)
			newPopulation = append(newPopulation, child)
		}

		best := findBestChromosome(newPopulation)
		bestFitnesses[gen].X = float64(gen)
		bestFitnesses[gen].Y = best.Fitness

		population = newPopulation
	}

	best := findBestChromosome(population)

	return best, bestFitnesses
