			child := crossover(parent1, parent2)
			mutate(child, conf.MutationChance)

			child.Score = calculateScore(child, exp)
			newPopulation = append(newPopulation, child)
		}

		population = newPopulation
	}

	return findBestChromosome(population)
}

func calculateScore(chr Chromosome, exp Expenses) float64 {
	totalFixedExp := 0.0
	for _, e := range exp.Fixed {
		totalFixedExp += e
	}
	totalVariableExp := 0.0
	for i, e := range chr.Values {
		totalVariableExp += e * exp.Variable[i]
	}
	totalExp := totalFixedExp + totalVariableExp
	diff := exp.TotalBudget - totalExp
	if diff >= 0 {
		return diff
	}

	penalty := -5.0 * diff
	for i, value := range chr.Values {
		penalty -= value * float64(exp.Priority[i])
	}

	return penalty
}

func initializePopulation(populationSize, numVariables int) []Chromosome {
	population := make([]Chromosome, populationSize)

	for i := 0; i < populationSize; i++ {
		chrom := Chromosome{
			Values: make([]float64, numVariables),
		}

		for j := 0; j < numVariables; j++ {
			chrom.Values[j] = rand.Float64()
		}

		population[i] = chrom
	}

	return population
}

func selectParent(population []Chromosome) Chromosome {
	idx1 := rand.Intn(len(population))
	idx2 := rand.Intn(len(population))

	if population[idx1].Score >= population[idx2].Score {
		return population[idx1]
	}

	return population[idx2]
}

func crossover(parent1, parent2 Chromosome) Chromosome {
	child := Chromosome{
		Values: make([]float64, len(parent1.Values)),
	}

	point := rand.Intn(len(parent1.Values))

	for i := 0; i < len(parent1.Values); i++ {
		if i < point {
			child.Values[i] = parent1.Values[i]
		} else {
			child.Values[i] = parent2.Values[i]
		}
	}

	return child
}

func mutate(chr Chromosome, mutationChance float64) {
	for i := 0; i < len(chr.Values); i++ {
		if rand.Float64() <= mutationChance {
			chr.Values[i] = rand.Float64()
		}
	}
}

func findBestChromosome(population []Chromosome) Chromosome {
	best := population[0]

	for _, chr := range population {
		if chr.Score > best.Score {
			best = chr
		}
	}

	return best
}
```

